const { embedding } = await embed('환불 어떻게 받나요');
// [0.021, -0.13, 0.08, ...]  ← 의미가 담긴 좌표

// 유사도 = 코사인 (방향이 얼마나 같나, -1~1)
function cosine(a, b) {
  const dot = a.reduce((s, x, i) => s + x * b[i], 0);
  const na = Math.hypot(...a), nb = Math.hypot(...b);
  return dot / (na * nb);
}
// 질문 벡터와 모든 조각 벡터의 유사도 -> 높은 순 정렬

